CREATE TYPE "ContactStatus" AS ENUM ('UNREAD','IN_PROGRESS','RESOLVED','SPAM');
CREATE TYPE "ContentStatus" AS ENUM ('DRAFT','PUBLISHED');
CREATE TYPE "ContentGroup" AS ENUM ('HOME','ABOUT','CONTACT','FOOTER','ACTIVITIES','SOCIAL_LINKS');
ALTER TABLE "contact_submissions" ADD COLUMN "status" "ContactStatus" NOT NULL DEFAULT 'UNREAD', ADD COLUMN "assignedToId" TEXT, ADD COLUMN "resolvedAt" TIMESTAMP(3), ADD COLUMN "spamAt" TIMESTAMP(3), ADD COLUMN "retainUntil" TIMESTAMP(3);
CREATE INDEX "contact_submissions_status_createdAt_idx" ON "contact_submissions"("status","createdAt");
CREATE INDEX "contact_submissions_assignedToId_idx" ON "contact_submissions"("assignedToId");
ALTER TABLE "contact_submissions" ADD CONSTRAINT "contact_submissions_assignedToId_fkey" FOREIGN KEY ("assignedToId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "contact_replies" ("id" TEXT NOT NULL,"submissionId" TEXT NOT NULL,"sentById" TEXT NOT NULL,"subject" TEXT NOT NULL,"body" TEXT NOT NULL,"method" TEXT NOT NULL,"deliveryStatus" TEXT NOT NULL DEFAULT 'recorded',"sentAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "contact_replies_pkey" PRIMARY KEY ("id"));
CREATE INDEX "contact_replies_submissionId_sentAt_idx" ON "contact_replies"("submissionId","sentAt");
ALTER TABLE "contact_replies" ADD CONSTRAINT "contact_replies_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "contact_submissions"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "contact_replies" ADD CONSTRAINT "contact_replies_sentById_fkey" FOREIGN KEY ("sentById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "app_settings" ("key" TEXT NOT NULL,"value" TEXT NOT NULL,"updatedBy" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "app_settings_pkey" PRIMARY KEY ("key"));
CREATE TABLE "public_content" ("id" TEXT NOT NULL,"group" "ContentGroup" NOT NULL,"status" "ContentStatus" NOT NULL DEFAULT 'DRAFT',"draftData" JSONB NOT NULL,"publishedData" JSONB,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "public_content_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "public_content_group_key" ON "public_content"("group");
CREATE TABLE "public_content_versions" ("id" TEXT NOT NULL,"contentId" TEXT NOT NULL,"editorId" TEXT NOT NULL,"data" JSONB NOT NULL,"action" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "public_content_versions_pkey" PRIMARY KEY ("id"));
CREATE INDEX "public_content_versions_contentId_createdAt_idx" ON "public_content_versions"("contentId","createdAt");
ALTER TABLE "public_content_versions" ADD CONSTRAINT "public_content_versions_contentId_fkey" FOREIGN KEY ("contentId") REFERENCES "public_content"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "public_content_versions" ADD CONSTRAINT "public_content_versions_editorId_fkey" FOREIGN KEY ("editorId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "committee_profiles" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"position" TEXT NOT NULL,"biography" TEXT NOT NULL,"photoUrl" TEXT,"displayOrder" INTEGER NOT NULL DEFAULT 0,"termStart" TIMESTAMP(3),"termEnd" TIMESTAMP(3),"status" "ContentStatus" NOT NULL DEFAULT 'DRAFT',"editedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "committee_profiles_pkey" PRIMARY KEY ("id"));
CREATE INDEX "committee_profiles_status_displayOrder_idx" ON "committee_profiles"("status","displayOrder");
ALTER TABLE "committee_profiles" ADD CONSTRAINT "committee_profiles_editedById_fkey" FOREIGN KEY ("editedById") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "email_verification_challenges" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"codeHash" TEXT NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "email_verification_challenges_pkey" PRIMARY KEY ("id"));
CREATE INDEX "email_verification_challenges_userId_createdAt_idx" ON "email_verification_challenges"("userId","createdAt");
